package com.telegram.avtobot;

import android.app.*; import android.os.*; import android.content.*; import android.graphics.Color; import android.text.*; import android.view.*; import android.widget.*; import java.util.*; import java.util.concurrent.*;

public class MainActivity extends Activity {
 private AppPrefs prefs; private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private EditText githubToken,githubRepo,token,chatTarget,scheduleTimes,groqKey,groqModel,geminiKey,geminiModel,openaiKey,openaiModel,topic,instruction,language,length,delay,retries; private Switch enabled; private Spinner provider; private TimePicker time; private TextView log,chatStatus,progressText,saveState; private ProgressBar progress; private boolean loading;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);prefs=new AppPrefs(this);bind();load();attachAutosave();}
 private void bind(){ githubToken=findViewById(R.id.githubToken);githubRepo=findViewById(R.id.githubRepo);token=findViewById(R.id.telegramToken);chatTarget=findViewById(R.id.chatTarget);scheduleTimes=findViewById(R.id.scheduleTimes);groqKey=findViewById(R.id.groqKey);groqModel=findViewById(R.id.groqModel);geminiKey=findViewById(R.id.geminiKey);geminiModel=findViewById(R.id.geminiModel);openaiKey=findViewById(R.id.openaiKey);openaiModel=findViewById(R.id.openaiModel);topic=findViewById(R.id.topic);instruction=findViewById(R.id.instruction);language=findViewById(R.id.language);length=findViewById(R.id.maxLength);delay=findViewById(R.id.checkDelay);retries=findViewById(R.id.retryCount);enabled=findViewById(R.id.enabled);provider=findViewById(R.id.provider);time=findViewById(R.id.sendTime);log=findViewById(R.id.log);chatStatus=findViewById(R.id.chatStatus);progress=findViewById(R.id.progress);progressText=findViewById(R.id.progressText);saveState=findViewById(R.id.saveState);provider.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Groq","Gemini","GPT/OpenAI"}));
  findViewById(R.id.publishOnline).setOnClickListener(v->publishOnline());findViewById(R.id.runOnline).setOnClickListener(v->runOnline());findViewById(R.id.syncChats).setOnClickListener(v->syncChats()); findViewById(R.id.loadModels).setOnClickListener(v->loadModels()); findViewById(R.id.historyButton).setOnClickListener(v->showHistory()); findViewById(R.id.testNow).setOnClickListener(v->sendNow()); enabled.setOnCheckedChangeListener((b,c)->{if(loading)return; saveValues(); if(c){AlarmReceiver.schedule(this); enabled.setText("Выключить отправку по времени");}else{AlarmReceiver.cancel(this);enabled.setText("Включить отправку по времени");} }); }
 private void load(){loading=true;githubToken.setText(prefs.get("github_token",""));githubRepo.setText(prefs.get("github_repo","ajtnazarovasirin-wq/telegram-auto-bot-1"));scheduleTimes.setText(prefs.get("schedule_times","09:00"));token.setText(prefs.token());chatTarget.setText(prefs.get("chat_target","@coding_222573g"));groqKey.setText(prefs.get("groq_key",""));groqModel.setText(prefs.get("groq_model","openai/gpt-oss-120b"));geminiKey.setText(prefs.get("gemini_key",""));geminiModel.setText(prefs.get("gemini_model","gemini-3.6-flash"));openaiKey.setText(prefs.get("openai_key",""));openaiModel.setText(prefs.get("openai_model","gpt-5-mini"));topic.setText(prefs.topic());instruction.setText(prefs.instruction());language.setText(prefs.language());length.setText(String.valueOf(prefs.maxLength()));delay.setText(String.valueOf(prefs.checkDelay()));retries.setText(String.valueOf(prefs.retries()));time.setHour(prefs.sendHour());time.setMinute(prefs.sendMinute());enabled.setChecked(prefs.getBoolean("enabled",false)); enabled.setText(enabled.isChecked()?"Выключить отправку по времени":"Включить отправку по времени");String pv=prefs.provider();provider.setSelection(Arrays.asList("Groq","Gemini","GPT/OpenAI").indexOf(pv));loading=false;}
 private void attachAutosave(){TextView.OnEditorActionListener noop=(v,a,e)->false; TextWatcher w=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){if(!loading){saveValues();saveState.setText("Сохранено автоматически");saveState.setTextColor(Color.rgb(19,121,91));}}public void afterTextChanged(Editable e){}}; EditText[] es={githubToken,githubRepo,token,chatTarget,scheduleTimes,groqKey,groqModel,geminiKey,geminiModel,openaiKey,openaiModel,topic,instruction,language,length,delay,retries};for(EditText e:es)e.addTextChangedListener(w);provider.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){if(!loading)saveValues();}});time.setOnTimeChangedListener((v,h,m)->{if(!loading)saveValues();});}
 private int n(EditText e,int d){try{return Integer.parseInt(e.getText().toString().trim());}catch(Exception x){return d;}}
 private void saveValues(){prefs.put("github_token",githubToken.getText().toString().trim());prefs.put("github_repo",githubRepo.getText().toString().trim());prefs.put("schedule_times",scheduleTimes.getText().toString().trim());prefs.put("telegram_token",token.getText().toString().trim());prefs.put("chat_target",chatTarget.getText().toString().trim());prefs.put("groq_key",groqKey.getText().toString().trim());prefs.put("groq_model",groqModel.getText().toString().trim());prefs.put("gemini_key",geminiKey.getText().toString().trim());prefs.put("gemini_model",geminiModel.getText().toString().trim());prefs.put("openai_key",openaiKey.getText().toString().trim());prefs.put("openai_model",openaiModel.getText().toString().trim());prefs.put("provider",provider.getSelectedItem().toString());prefs.put("topic",topic.getText().toString().trim());prefs.put("instruction",instruction.getText().toString().trim());prefs.put("language",language.getText().toString().trim());prefs.putInt("max_length",n(length,500));prefs.putInt("check_delay",n(delay,5));prefs.putInt("retries",n(retries,2));prefs.putInt("send_hour",time.getHour());prefs.putInt("send_minute",time.getMinute());prefs.putBoolean("all_chats",((RadioButton)findViewById(R.id.allChats)).isChecked());prefs.putBoolean("enabled",enabled.isChecked());String target=chatTarget.getText().toString().trim();if(!target.isEmpty()){HashSet<String> ids=new HashSet<>();ids.add(target);getSharedPreferences("chats",0).edit().putStringSet("ids",ids).putStringSet("all_ids",ids).apply();}}
 private String onlineConfig(){org.json.JSONObject o=new org.json.JSONObject();try{o.put("enabled",enabled.isChecked());o.put("timezone",java.util.TimeZone.getDefault().getID());org.json.JSONArray schedules=new org.json.JSONArray();for(String raw:scheduleTimes.getText().toString().split(",")){String tm=raw.trim();if(tm.matches("[0-9]{1,2}:[0-9]{2}"))schedules.put(new org.json.JSONObject().put("time",tm).put("days",new org.json.JSONArray().put("mon").put("tue").put("wed").put("thu").put("fri").put("sat").put("sun")));}if(schedules.length()==0)schedules.put(new org.json.JSONObject().put("time",String.format(java.util.Locale.US,"%02d:%02d",time.getHour(),time.getMinute())).put("days",new org.json.JSONArray().put("mon").put("tue").put("wed").put("thu").put("fri").put("sat").put("sun")));o.put("schedules",schedules);o.put("chat_ids",new org.json.JSONArray().put(chatTarget.getText().toString().trim()));o.put("topic",topic.getText().toString().trim());o.put("instruction",instruction.getText().toString().trim());o.put("language",language.getText().toString().trim());o.put("max_length",n(length,700));o.put("provider",provider.getSelectedItem().toString().equals("GPT/OpenAI")?"openai":provider.getSelectedItem().toString().toLowerCase());o.put("model",provider.getSelectedItem().toString().equals("Gemini")?geminiModel.getText().toString().trim():provider.getSelectedItem().toString().equals("GPT/OpenAI")?openaiModel.getText().toString().trim():groqModel.getText().toString().trim());o.put("check_after_minutes",n(delay,5));o.put("retries",n(retries,2));o.put("history_limit",20);return o.toString(2);}catch(Exception e){return "{}";}}
 private void publishOnline(){saveValues();String t=githubToken.getText().toString().trim(),r=githubRepo.getText().toString().trim();if(t.isEmpty()||r.isEmpty()){Toast.makeText(this,"Введи GitHub token и owner/name репозитория",Toast.LENGTH_LONG).show();return;}worker.execute(()->{try{GitHubClient.updateConfig(r,t,onlineConfig());runOnUiThread(()->Toast.makeText(this,"Настройки переданы онлайн",Toast.LENGTH_LONG).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Ошибка передачи: "+e.getMessage(),Toast.LENGTH_LONG).show());}});}
 private void runOnline(){publishOnline();worker.execute(()->{try{Thread.sleep(500);GitHubClient.runNow(githubRepo.getText().toString().trim(),githubToken.getText().toString().trim());runOnUiThread(()->Toast.makeText(this,"Онлайн-запуск отправлен в GitHub Actions",Toast.LENGTH_LONG).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Ошибка онлайн-запуска: "+e.getMessage(),Toast.LENGTH_LONG).show());}});}
 private void sendNow(){saveValues();progress.setVisibility(View.VISIBLE);progressText.setText("1/3  Отправлен запрос в ИИ…");progressText.setTextColor(Color.rgb(124,58,237));worker.execute(()->{try{Thread.sleep(250);runOnUiThread(()->progressText.setText("2/3  Ответ ИИ получен. Отправка в Telegram…"));Sender.run(this);Thread.sleep(250);runOnUiThread(()->{progressText.setText("3/3  Ответ успешно отправлен в Telegram");progressText.setTextColor(Color.rgb(19,121,91));log.setText("Готово\nПроверь канал или чат. Подробности находятся в истории.");});}catch(Exception e){runOnUiThread(()->{progressText.setText("Ошибка");progressText.setTextColor(Color.RED);log.setText(e.getMessage());});}});}
 private void loadModels(){saveValues();String pv=provider.getSelectedItem().toString();String key=pv.equals("Gemini")?geminiKey.getText().toString().trim():pv.equals("GPT/OpenAI")?openaiKey.getText().toString().trim():groqKey.getText().toString().trim();if(key.isEmpty()){Toast.makeText(this,"Сначала введи API-ключ выбранного ИИ",Toast.LENGTH_SHORT).show();return;}worker.execute(()->{try{org.json.JSONArray a=ApiClient.listModels(pv,key);String[] ids=new String[a.length()];for(int i=0;i<a.length();i++)ids[i]=a.getString(i);runOnUiThread(()->chooseModel(pv,ids));}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Не удалось загрузить модели: "+e.getMessage(),Toast.LENGTH_LONG).show());}});}
 private void chooseModel(String pv,String[] ids){if(ids.length==0){Toast.makeText(this,"API не вернул доступные модели",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("Выбери доступную модель").setItems(ids,(d,w)->{if(pv.equals("Gemini"))geminiModel.setText(ids[w]);else if(pv.equals("GPT/OpenAI"))openaiModel.setText(ids[w]);else groqModel.setText(ids[w]);saveValues();}).show();}
 private void syncChats(){String t=token.getText().toString().trim();if(t.isEmpty()){chatStatus.setText("Введи токен бота");return;}worker.execute(()->{try{String r=ApiClient.telegramGetUpdates(t);org.json.JSONArray a=new org.json.JSONObject(r).optJSONArray("result");HashSet<String> ids=new HashSet<>();if(a!=null)for(int i=0;i<a.length();i++){org.json.JSONObject u=a.getJSONObject(i),m=u.optJSONObject("message");if(m==null)m=u.optJSONObject("channel_post");if(m!=null&&m.optJSONObject("chat")!=null)ids.add(String.valueOf(m.getJSONObject("chat").getLong("id")));}getSharedPreferences("chats",0).edit().putStringSet("all_ids",ids).apply();runOnUiThread(()->chooseChats(ids));}catch(Exception e){runOnUiThread(()->chatStatus.setText("Ошибка Telegram: "+e.getMessage()));}});}
 private void chooseChats(HashSet<String> ids){if(ids.isEmpty()){chatStatus.setText("Чаты не найдены. Для канала используй @username и добавь бота администратором.");return;}String[] a=ids.toArray(new String[0]);HashSet<String> old=new HashSet<>(getSharedPreferences("chats",0).getStringSet("ids",new HashSet<>()));boolean[] checked=new boolean[a.length];for(int i=0;i<a.length;i++)checked[i]=old.contains(a[i]);new AlertDialog.Builder(this).setTitle("Выбери группы, каналы и чаты").setMultiChoiceItems(a,checked,(d,w,c)->{}).setPositiveButton("Готово",(d,w)->{ListView l=((AlertDialog)d).getListView();HashSet<String> chosen=new HashSet<>();for(int i=0;i<a.length;i++)if(l.isItemChecked(i))chosen.add(a[i]);getSharedPreferences("chats",0).edit().putStringSet("ids",chosen).apply();chatStatus.setText("Сохранено чатов: "+chosen.size());}).show();}
 private void showHistory(){android.content.SharedPreferences h=getSharedPreferences("history",0);StringBuilder s=new StringBuilder("Статус: ").append(h.getString("status","ещё нет")).append("\nОшибка: ").append(h.getString("last_error","нет")).append("\n\nПоследние тексты:\n");for(String x:h.getStringSet("texts",new HashSet<>()))s.append("— ").append(x).append("\n");new AlertDialog.Builder(this).setTitle("История и отчёт").setMessage(s.toString()).setPositiveButton("Закрыть",null).show();}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
